fields.InputDefinition:
{
  "goal": "Open the 'MJ: AI Agent Runs' entity grid — type 'AI Agent Runs' in the LEFT sidebar 'Search entities...' box and click the 'MJ: AI Agent Runs' node (or navigate to http://localhost:4200/app/data-explorer/Data?entity=MJ:%20AI%20Agent%20Runs). Click a row whose Status is 'Completed', then click 'Open Full Record'. The AI Agent Run detail opens with a header (the agent name e.g. 'Memory Manager', a COMPLETED badge, and Started/Completed/Duration/Result fields) and a row of tabs: Timeline, Visualization, Analytics, Details. Click the 'Visualization' tab. Verify the Visualization view renders a visual representation of the agent run (a graph / diagram / flow of the run's steps or execution), with no error. (Seeing the visualization render — not a specific shape — is success.) Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "A Completed AI Agent Run record opened",
    "The 'Visualization' tab was selected and rendered a visual representation of the run (graph/diagram/flow)",
    "No error messages, blank screens, or crash pages"
  ]
}
